        char not in _HEX_DIGITS for char in fingerprint
    ):
        raise ValueError(
            f"{name} fingerprint must be 64 lowercase hex characters"
        )
    for flag_name in ("consensus", "passed"):
        if not isinstance(summary[flag_name], bool):
